#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <pthread.h>

#define MAX_IMAGE_SIZE (64 * 1024 * 1024)
#define CIRCUIT_BREAKER_THRESHOLD 5
#define CIRCUIT_BREAKER_TIMEOUT 30
#define PIPELINE_STAGES 4

typedef enum { CB_CLOSED, CB_OPEN, CB_HALF_OPEN } cb_state_t;

typedef struct {
    cb_state_t state;
    int failure_count;
    time_t last_failure_time;
    pthread_mutex_t lock;
} circuit_breaker_t;

typedef struct {
    unsigned char *data;
    size_t size;
    int width;
    int height;
    int channels;
} image_t;

typedef struct {
    char filepath[4096];
    struct stat file_stat;
    int validated;
} image_request_t;

static circuit_breaker_t g_breaker = {
    .state = CB_CLOSED,
    .failure_count = 0,
    .last_failure_time = 0,
    .lock = PTHREAD_MUTEX_INITIALIZER
};

int cb_allow_request(circuit_breaker_t *cb) {
    pthread_mutex_lock(&cb->lock);
    if (cb->state == CB_OPEN) {
        time_t now = time(NULL);
        if (difftime(now, cb->last_failure_time) > CIRCUIT_BREAKER_TIMEOUT) {
            cb->state = CB_HALF_OPEN;
            pthread_mutex_unlock(&cb->lock);
            return 1;
        }
        pthread_mutex_unlock(&cb->lock);
        return 0;
    }
    pthread_mutex_unlock(&cb->lock);
    return 1;
}

void cb_record_success(circuit_breaker_t *cb) {
    pthread_mutex_lock(&cb->lock);
    cb->failure_count = 0;
    cb->state = CB_CLOSED;
    pthread_mutex_unlock(&cb->lock);
}

void cb_record_failure(circuit_breaker_t *cb) {
    pthread_mutex_lock(&cb->lock);
    cb->failure_count++;
    cb->last_failure_time = time(NULL);
    if (cb->failure_count >= CIRCUIT_BREAKER_THRESHOLD) {
        cb->state = CB_OPEN;
    }
    pthread_mutex_unlock(&cb->lock);
}

/* Stage 1: Validate file metadata and cache stat result */
int pipeline_validate(image_request_t *req) {
    if (stat(req->filepath, &req->file_stat) != 0) {
        return -1;
    }
    if (!S_ISREG(req->file_stat.st_mode)) {
        return -1;
    }
    if (req->file_stat.st_size > MAX_IMAGE_SIZE) {
        return -1;
    }
    if (req->file_stat.st_size == 0) {
        return -1;
    }
    /* Check file is not a symlink */
    struct stat lstat_buf;
    if (lstat(req->filepath, &lstat_buf) != 0) {
        return -1;
    }
    if (S_ISLNK(lstat_buf.st_mode)) {
        return -1;
    }
    req->validated = 1;
    return 0;
}

/* Stage 2: Apply circuit breaker check */
int pipeline_circuit_check(image_request_t *req) {
    if (!req->validated) {
        return -1;
    }
    return cb_allow_request(&g_breaker) ? 0 : -1;
}

/* Stage 3: Load image data using cached stat for allocation */
image_t *pipeline_load(image_request_t *req) {
    if (!req->validated) {
        return NULL;
    }

    /* Use the validated file size for buffer allocation */
    size_t alloc_size = (size_t)req->file_stat.st_size;

    int fd = open(req->filepath, O_RDONLY);
    if (fd < 0) {
        cb_record_failure(&g_breaker);
        return NULL;
    }

    image_t *img = calloc(1, sizeof(image_t));
    if (!img) {
        close(fd);
        cb_record_failure(&g_breaker);
        return NULL;
    }

    img->data = malloc(alloc_size);
    if (!img->data) {
        free(img);
        close(fd);
        cb_record_failure(&g_breaker);
        return NULL;
    }

    /* Read the actual file content - file may have changed since stat */
    ssize_t total_read = 0;
    ssize_t bytes_read;
    while (total_read < (ssize_t)alloc_size) {
        bytes_read = read(fd, img->data + total_read, alloc_size - total_read);
        if (bytes_read <= 0) break;
        total_read += bytes_read;
    }

    close(fd);
    img->size = (size_t)total_read;
    cb_record_success(&g_breaker);
    return img;
}

/* Stage 4: Process image (grayscale conversion) */
int pipeline_process(image_t *img) {
    if (!img || !img->data || img->size < 12) {
        return -1;
    }

    /* Parse simple raw image header: width(4) height(4) channels(4) */
    memcpy(&img->width, img->data, 4);
    memcpy(&img->height, img->data + 4, 4);
    memcpy(&img->channels, img->data + 8, 4);

    if (img->width <= 0 || img->height <= 0 || img->channels <= 0) {
        return -1;
    }

    size_t expected_size = 12 + (size_t)img->width * img->height * img->channels;
    if (img->size < expected_size) {
        return -1;
    }

    /* Grayscale conversion */
    unsigned char *pixels = img->data + 12;
    if (img->channels >= 3) {
        for (int i = 0; i < img->width * img->height; i++) {
            int offset = i * img->channels;
            unsigned char gray = (unsigned char)(
                0.299 * pixels[offset] +
                0.587 * pixels[offset + 1] +
                0.114 * pixels[offset + 2]
            );
            pixels[offset] = gray;
            pixels[offset + 1] = gray;
            pixels[offset + 2] = gray;
        }
    }

    return 0;
}

int process_image_pipeline(const char *filepath) {
    image_request_t req;
    memset(&req, 0, sizeof(req));

    if (strlen(filepath) >= sizeof(req.filepath)) {
        return -1;
    }
    strncpy(req.filepath, filepath, sizeof(req.filepath) - 1);

    /* Pipeline Stage 1 */
    if (pipeline_validate(&req) != 0) {
        fprintf(stderr, "Validation failed for: %s\n", req.filepath);
        return -1;
    }

    /* Pipeline Stage 2 */
    if (pipeline_circuit_check(&req) != 0) {
        fprintf(stderr, "Circuit breaker open\n");
        return -1;
    }

    /* Pipeline Stage 3 */
    image_t *img = pipeline_load(&req);
    if (!img) {
        fprintf(stderr, "Load failed for: %s\n", req.filepath);
        return -1;
    }

    /* Pipeline Stage 4 */
    int result = pipeline_process(img);

    free(img->data);
    free(img);
    return result;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <image_path>\n", argv[0]);
        return 1;
    }

    int ret = process_image_pipeline(argv[1]);
    if (ret == 0) {
        printf("Image processed successfully\n");
    } else {
        printf("Image processing failed\n");
    }
    return ret;
}
